// Kuracare: replaces the MainActivity generated by dx (scripts/apk-release.sh
// copies it over). Only addition: hand the invitation that opened the app, if
// any, to org.kuracare.app.Bridge, where Rust picks it up; and the results of the
// system file picker (export, backup).
package dev.dioxus.main

import android.content.Intent
import android.os.Bundle

typealias BuildConfig = org.kuracare.app.BuildConfig

class MainActivity : WryActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        org.kuracare.app.Bridge.noteIntent(this, intent)
    }

    @Deprecated("Activity results for the system file picker (Bridge.saveDocument/openDocument)")
    @Suppress("DEPRECATION")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        if (!org.kuracare.app.Bridge.onDocResult(this, requestCode, resultCode, data)) {
            super.onActivityResult(requestCode, resultCode, data)
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        org.kuracare.app.Bridge.noteIntent(this, intent)
    }
}
